-- Adds COLLECTOR_CODE to PROJECT.
-- Per-project 5-char code (A-Z), same pattern as roadmap's per-user
-- ADM_USER.COLLECTOR_CODE — generated by route-backend at project creation
-- and lazily backfilled on first read for pre-existing rows.

ALTER TABLE dbo.PROJECT
ADD COLLECTOR_CODE VARCHAR(10) NULL;
GO

